// SPDX-License-Identifier: MIT
pragma solidity 0.8.27;

import {Test} from "forge-std/Test.sol";
import {ClausProjectWallet} from "src/ClausProjectWallet.sol";

/// A pre-signed renewal (generation 2) whose validAfter lies in the future can be
/// submitted by any third party while generation 1 is still live. authorizeSession
/// never checks s.validAfter against block.timestamp and never checks that the live
/// generation has expired, so the submission replaces the live session immediately:
/// generation-1 payments stop working and generation-2 payments cannot start until
/// validAfter. Expected: the live generation keeps paying until its validUntil.
contract WalletEarlyRenewalTest is Test {
    uint256 constant OWNER_KEY = 0xB0B;
    uint256 constant SESSION_KEY = 0xA11CE;
    bytes32 constant SESSION = keccak256("provider-payment-session");
    address constant RECIPIENT = address(0xBEEF);
    ClausProjectWallet wallet;

    function setUp() public {
        vm.warp(1800000000);
        wallet = new ClausProjectWallet(vm.addr(OWNER_KEY));
        vm.deal(address(wallet), 10 ether);
    }

    function sig(uint256 key, bytes32 hash) internal pure returns (bytes memory) {
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(key, hash);
        return abi.encodePacked(r, s, v);
    }

    function testThirdPartyCannotCutOffLiveGenerationWithPreSignedRenewal() public {
        uint64 start = uint64(block.timestamp);
        // Generation 1: live now, for one day.
        ClausProjectWallet.SessionAuthorization memory gen1 = ClausProjectWallet.SessionAuthorization(
            SESSION, vm.addr(SESSION_KEY), address(0), RECIPIENT, 1 ether, 2 ether, start, start + 1 days, 1, start + 1 hours
        );
        wallet.authorizeSession(gen1, sig(OWNER_KEY, wallet.sessionDigest(gen1)));

        // Owner pre-signs generation 2 to take over once generation 1 ends (validAfter = gen1.validUntil).
        ClausProjectWallet.SessionAuthorization memory gen2 = ClausProjectWallet.SessionAuthorization(
            SESSION, vm.addr(SESSION_KEY), address(0), RECIPIENT, 1 ether, 2 ether,
            start + 1 days, start + 2 days, 2, start + 1 days + 1 hours
        );
        bytes memory renewal = sig(OWNER_KEY, wallet.sessionDigest(gen2));

        // A third party submits the renewal immediately, long before generation 1 expires.
        // On fixed code this call is rejected; the outcome is ignored so the assertion below decides.
        vm.prank(address(0xBAD));
        (bool submitted,) = address(wallet).call(abi.encodeCall(wallet.authorizeSession, (gen2, renewal)));
        submitted;

        // Expected: generation 1 is still payable until start + 1 days.
        // Actual on current code: the live session was replaced; pay() reverts InvalidPayment.
        ClausProjectWallet.Payment memory p = ClausProjectWallet.Payment(
            SESSION, 1, address(0), RECIPIENT, 1 ether, keccak256("quote-1"), 1, start + 1 hours
        );
        wallet.pay(p, sig(SESSION_KEY, wallet.paymentDigest(p)));
        assertEq(RECIPIENT.balance, 1 ether);
    }
}

