pragma solidity 0.8.27;
import {Test} from "forge-std/Test.sol";
import {ClausReadonlyProject} from "src/ClausReadonlyProject.sol";
import {ClausNativeVault} from "src/ClausNativeVault.sol";

/// Admission module with a larger configuration (for example an allowlist). It
/// returns the canonical (bool,uint256) result the vault expects and admits everyone.
contract WideConfigAdmission {
    function evaluate(bytes calldata configuration, bytes calldata input) external pure returns (bytes memory) {
        if (configuration.length == 0 || input.length != 96) revert();
        return abi.encode(true, type(uint256).max);
    }
}

contract VaultPolicyGasProofTest is Test {
    receive() external payable {}

    function testDepositAdmittedWhenPolicyConfigurationIsWithinProjectBounds() public {
        WideConfigAdmission module = new WideConfigAdmission();
        // 4096 bytes is within the 8192-byte configuration bound ClausReadonlyProject enforces.
        ClausReadonlyProject policy = new ClausReadonlyProject(bytes32("wide"), address(module), new bytes(4096));
        // The policy answers correctly when called directly.
        assertEq(policy.evaluate(abi.encode(address(this), uint256(1 ether), uint256(1 ether))),
            abi.encode(true, type(uint256).max));
        ClausNativeVault vault = new ClausNativeVault(address(policy));
        // Expected: the policy admits, so the deposit succeeds.
        // Actual on current code: POLICY_GAS (250_000) is exhausted reading the
        // configuration from storage, the staticcall fails and deposit reverts DepositDenied.
        vault.deposit{value: 1 ether}();
        assertEq(vault.principal(address(this)), 1 ether);
    }
}

